(function() {
 var cards = document.querySelectorAll('.ss-cform__card');
 var inquiryInput = document.getElementById('ss-inquiry-type');
 var typeMap = {
 'discovery_call': 'Book a Discovery Call',
 'demo_request': 'Request a Demo',
 'general_inquiry': 'General Inquiry'
 };

 function setHiddenField(form, name, value) {
 var field = form.find('[name="' + name + '"]');
 if (field.length) { field.val(value).trigger('change'); }
 }

 function syncDropdown(dataType) {
 if (window.ssHSForm) {
 setHiddenField(window.ssHSForm, 'enquiry_type', typeMap[dataType]);
 }
 }

 cards.forEach(function(card) {
 card.addEventListener('click', function() {
 cards.forEach(function(c) { c.classList.remove('is-active'); });
 card.classList.add('is-active');
 var dataType = card.getAttribute('data-type');
 if (inquiryInput) inquiryInput.value = dataType;
 syncDropdown(dataType);
 });
 });

 var PORTAL_ID = '47793787';
 var FORM_ID = 'e1b515e9-db78-43f7-8b8d-4389dadde429';

 function loadHSForm() {
 if (typeof hbspt === 'undefined') {
 var script = document.createElement('script');
 script.src = '//js.hsforms.net/forms/embed/v2.js';
 script.charset = 'utf-8';
 script.type = 'text/javascript';
 script.onload = createForm;
 document.head.appendChild(script);
 } else {
 createForm();
 }
 }

 function createForm() {
 if (PORTAL_ID === '#' || FORM_ID === '#') {
 var target = document.getElementById('ss-hs-form-target');
 if (target) {
 target.innerHTML = '⚠️ Form will appear here once Hub ID and Form ID are set.
';
 }
 return;
 }
 hbspt.forms.create({
 portalId: PORTAL_ID,
 formId: FORM_ID,
 target: '#ss-hs-form-target',
 onFormReady: function(form) {
 window.ssHSForm = form;
 setHiddenField(form, 'enquiry_type', 'Book a Discovery Call');
 },
 onFormSubmitted: function() {
 var formWrap = document.getElementById('ss-hs-form-target');
 var cardsEl = document.querySelector('.ss-cform__cards');
 var heading = document.querySelector('.ss-cform__form-heading');
 var thankyou = document.getElementById('ss-thankyou');
 var inquiryHidden = document.getElementById('ss-inquiry-type');
 if (formWrap) formWrap.style.display = 'none';
 if (cardsEl) cardsEl.style.display = 'none';
 if (heading) heading.style.display = 'none';
 if (inquiryHidden) inquiryHidden.style.display = 'none';
 if (thankyou) thankyou.style.display = 'block';
 }
 });
 }

 if (document.readyState === 'loading') {
 document.addEventListener('DOMContentLoaded', loadHSForm);
 } else {
 loadHSForm();
 }
})();

