 ];

 async function initMap() {
 const { Map, InfoWindow } = await google.maps.importLibrary("maps");
 const { AdvancedMarkerElement } = await google.maps.importLibrary("marker");
 let center = { lat: parseFloat(53.20892861789777), lng: parseFloat(-0.1153298408464462) };

 const map = new Map(document.getElementById("gMap"), {
 center: center,
 zoom: 16,
 mapId: "TJS_MAP"
 });

 const infoWindow = new InfoWindow();
 const bounds = new google.maps.LatLngBounds();

 markers.forEach((location) => {
 const markerIcon = document.createElement("img");
 markerIcon.src = location.icon;
 markerIcon.alt = location.text;

 const marker = new AdvancedMarkerElement({
 map,
 position: { lat: location.lat, lng: location.lng },
 content: markerIcon
 });

 marker.addListener("click", () => {
 infoWindow.close();
 infoWindow.setContent(`${location.text}
`);
 infoWindow.open(map, marker);
 map.panTo({ lat: location.lat, lng: location.lng }); 
 });

 bounds.extend({ lat: location.lat, lng: location.lng });
 });
 }

